  $("wk").textContent="Week of "+S.week.getDate()+(sameM?"":" "+S.week.toLocaleDateString("en-GB",{month:"short"}))+" – "+e.getDate()+" "+e.toLocaleDateString("en-GB",{month:"short",year:"numeric"});
