  const rows=[["Address",p.site],["Location",p.lat!=null?fmtCoord(p.lat,p.lon)+(p.siteLoc?" (site's saved location: the phone didn't record one)":" (from the phone's GPS)"):"Not recorded in photo. The phone didn't save a location with it."],["Altitude",p.alt!=null?(+p.alt).toFixed(2)+" m":""],["Date & time",stampTime(p.takenAt)],["Weather",p.weather],
    ["Project",p.project],["Plot",p.plot],["Folder (stage)",p.category],["Note",p.caption],["Taken by",owner?nameOf(who):(S.myProfile&&S.myProfile.name)],["Trade",p.trade],["Sent",stamp(p.created)]].filter(x=>x[1]);
