let jsPdfP=null;
function loadJsPdf(){if(window.jspdf)return Promise.resolve();if(jsPdfP)return jsPdfP;jsPdfP=new Promise((res,rej)=>{const s=document.createElement("script");s.src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";s.onload=res;s.onerror=()=>{jsPdfP=null;rej(new Error("load"))};document.head.appendChild(s)});return jsPdfP}
async function pdfRecord(rec){
  if(!S.dl){toast("Downloads only work when the page is opened in claude.ai");return}
  toast("Making the PDF…");
  try{await loadJsPdf()}catch(e){toast("Couldn't load the PDF maker. Check your connection.");return}
  const doc=new window.jspdf.jsPDF({unit:"mm",format:"a4"}); const W=210,M=16; let y=18;
  const clean=t=>String(t||"").replace(/[–—]/g,"-").replace(/[‘’]/g,"'").replace(/[“”]/g,'"').replace(/[^\x09\x0A\x0D\x20-\x7E£·•°]/g,"");
  const need=h=>{if(y+h>282){doc.addPage();y=18}};
  const text=(t,size=10,style="normal",indent=0,gap=1.6)=>{doc.setFont("helvetica",style);doc.setFontSize(size);const lines=doc.splitTextToSize(clean(t),W-2*M-indent);lines.forEach(l=>{need(size*0.45);doc.text(l,M+indent,y);y+=size*0.42})
    ;y+=gap};
  doc.setFillColor(...BRGB());doc.rect(0,0,W,6,"F");
  await pdfLogo(doc,W-M,11,52,24);
  text("JEB BUILDING SERVICES",9,"bold",0,6); text("Site induction record",18,"bold",0,2); text(rec.site,12,"bold",0,4);
  const w=rec.worker||{};
  const rows=(list)=>list.filter(x=>x[1]).forEach(([l,v])=>{doc.setFont("helvetica","bold");doc.setFontSize(9.5);need(6);doc.text(clean(l),M,y);
    doc.setFont("helvetica","normal");const lines=doc.splitTextToSize(clean(v),W-2*M-62);lines.forEach((ln,i)=>{if(i)need(5);doc.text(ln,M+62,y);y+=4.3});y+=1.4});
  text("Site information",11,"bold",0,1.5); rows(IND_DETAILS.map(([k,l])=>[l,rec.details&&rec.details[k]])); y+=2;
  if(rec.rulesAgreed){text("Site rules",11,"bold",0,1.5);need(6);doc.setDrawColor(40);doc.rect(M,y-3.2,3.6,3.6);doc.setLineWidth(0.5);doc.line(M+0.7,y-1.4,M+1.6,y-0.3);doc.line(M+1.6,y-0.3,M+3.1,y-2.6);doc.setLineWidth(0.2);
    text(`Read the site rules (${(rec.rulesAgreed.docs||[]).join(", ")}) and agreed: "I have read the site rules and I will follow them."`,9.5,"normal",6,3)}
  text("Points confirmed by the worker",11,"bold",0,1.5);
  (rec.items||[]).forEach(t=>{need(6);doc.setDrawColor(40);doc.rect(M,y-3.2,3.6,3.6);doc.setLineWidth(0.5);doc.line(M+0.7,y-1.4,M+1.6,y-0.3);doc.line(M+1.6,y-0.3,M+3.1,y-2.6);doc.setLineWidth(0.2);text(t,9.5,"normal",6,1.2)});
  y+=2; text("Worker",11,"bold",0,1.5);
  rows([["Name",rec.name],["Role",rec.role],["Company",w.company],[rec.onDevice?"Trade or reason":"Trade",w.trade],["Card number",w.cscs],["Emergency contact",[w.ecName,w.ecPhone].filter(Boolean).join(", ")],["Medical / other",w.medical]]);
  need(52); y+=2; text("Signature",11,"bold",0,1.5);
  try{doc.addImage(rec.signature,"PNG",M,y,75,25);doc.setDrawColor(180);doc.rect(M,y,75,25)}catch(e){}
  y+=30; text(rec.onDevice?`Signed electronically by ${rec.name} on ${stamp(rec.signedAt)}, in person on a JEB Building Services device.`:`Signed electronically by ${rec.name} on ${stamp(rec.signedAt)} using the JEB Building Services staff app, signed in to their own account.`,9,"normal",0,1);
  if(rec.deliveredAt&&rec.deliveredAt-rec.signedAt>600000) text(`Signed without signal; received ${stamp(rec.deliveredAt)}.`,9);
  const fn=`Induction - ${clean(rec.site).replace(/[^\w\s-]/g,"").trim()} - ${clean(rec.name).replace(/[^\w\s-]/g,"").trim()} - ${iso(new Date(rec.signedAt))}.pdf`;
  try{await S.dl.save({filename:fn,data:doc.output("blob")})}catch(e){if(!(e&&e.code==="declined"))toast("Download didn't go through")}
}

async function registerPdf(ind){
  if(!S.dl){toast("Downloads only work when the page is opened in claude.ai");return}
  toast("Making the register…");
  try{await loadJsPdf()}catch(e){toast("Couldn't load the PDF maker. Check your connection.");return}
  const doc=new window.jspdf.jsPDF({unit:"mm",format:"a4"}); const W=210,M=16; let y=18;
  const clean=t=>String(t||"").replace(/[–—]/g,"-").replace(/[‘’]/g,"'").replace(/[“”]/g,'"').replace(/[^\x09\x0A\x0D\x20-\x7E£·°]/g,"");
  const need=h=>{if(y+h>282){doc.addPage();y=18}};
  const text=(t,size=10,style="normal",indent=0,gap=1.6)=>{doc.setFont("helvetica",style);doc.setFontSize(size);doc.splitTextToSize(clean(t),W-2*M-indent).forEach(l=>{need(size*0.45);doc.text(l,M+indent,y);y+=size*0.42});y+=gap};
  doc.setFillColor(...BRGB());doc.rect(0,0,W,6,"F");
  await pdfLogo(doc,W-M,11,52,24);
  text("JEB BUILDING SERVICES",9,"bold",0,6); text("Site induction register",18,"bold",0,2); text(ind.site,12,"bold",0,1);
  const d=ind.details||{}; text(`Site manager: ${d.manager||"-"}   ·   Fire assembly point: ${d.assembly||"-"}`,9,"normal",0,1); text(`Printed ${stamp(Date.now())}. Full induction content is in each person's individual record.`,8.5,"normal",0,5);
  const rows=[];
  teamIds().forEach(id=>{sigsOf(S.data.signoffs[id]).filter(s=>s.inductionId===ind.id).forEach(s=>rows.push({name:s.name||nameOf(id),who:"Employee"+((s.worker||{}).company?" · "+s.worker.company:""),at:s.signedAt,sig:s.signature,v:s.version||1}))});
  allVisitInds().filter(v=>v.inductionId===ind.id).forEach(v=>rows.push({name:v.name,who:[v.role,(v.worker||{}).company].filter(Boolean).join(" · "),at:v.signedAt,sig:v.signature,v:v.version||1}));
  rows.sort((a,b)=>a.at-b.at);
  doc.setFont("helvetica","bold");doc.setFontSize(9);doc.text("Name",M,y);doc.text("Role / company",M+55,y);doc.text("Date and time",M+108,y);doc.text("Signature",W-M-44,y);y+=2;doc.setDrawColor(150);doc.line(M,y,W-M,y);y+=2;
  rows.forEach(r=>{need(18);doc.setFont("helvetica","normal");doc.setFontSize(9.5);doc.text(doc.splitTextToSize(clean(r.name),52),M,y+5);doc.setFontSize(8.5);doc.text(doc.splitTextToSize(clean(r.who),50),M+55,y+5);
    doc.text(clean(stamp(r.at))+((r.v<(ind.version||1))?" (older version)":""),M+108,y+5);try{doc.addImage(r.sig,"PNG",W-M-44,y,44,14.5)}catch(e){}doc.setDrawColor(215);doc.line(M,y+16,W-M,y+16);y+=18});
  if(!rows.length) text("Nobody has signed yet.",10);
  try{await S.dl.save({filename:`Induction register - ${clean(ind.site).replace(/[^\w\s-]/g,"").trim()}.pdf`,data:doc.output("blob")})}catch(e){if(!(e&&e.code==="declined"))toast("Download didn't go through")}
}

/* ================= JOB SHEETS & SNAG LISTS ================= */
const JOB_KINDS={job:"Job sheet",snag:"Snag list"};
const JOB_DET=[["ref","Job / reference no.","e.g. JEB-0142"],["client","Client","e.g. Mrs Jane Smith"],["phone","Client phone",""],["address","Address of the works","only needed if there's no site"],["contact","Contact on site","name and phone"],["start","Start date","","date"],["hours","Working hours","e.g. 8am–4.30pm"],["access","Access, parking & keys","e.g. key safe 1234, park on drive"],["price","Price / agreed cost (optional)","e.g. £2,450 + VAT"]];
const jobDetRead=()=>{const d={};JOB_DET.forEach(([k])=>{const el=$("jd-"+k);if(el&&el.value.trim())d[k]=el.value.trim()});["scope","mats","hs"].forEach(k=>{const el=$("jd-"+k);if(el&&el.value.trim())d[k]=el.value.trim()});return d};
const doneKey=(jobId,taskId)=>jobId+"__"+taskId;
function taskDone(job,t){return S.jobdone[doneKey(job.id,t.id)]}
function jobProgress(job){const n=(job.tasks||[]).length;const d=(job.tasks||[]).filter(t=>{const x=taskDone(job,t);return x&&x.done}).length;return {n,d}}
function myJobs(){return S.jobs.filter(j=>(j.assignees||[]).includes(S.me))}
function jobCard(j,owner){
  const {n,d}=jobProgress(j); const pct=n?Math.round(d/n*100):0;
  const late=j.status!=="closed"&&j.due&&j.due<iso(new Date())&&d<n;
  return `<button type="button" class="entry jobc" data-j="${esc(j.id)}"><div class="main">
    <div class="job"><span class="tag ${j.kind==="snag"?"day":""}">${JOB_KINDS[j.kind]||"Job sheet"}</span>${j.status==="closed"?'<span class="tag ok">Signed off</span>':d===n&&n?'<span class="tag ok">All ticked</span>':""}${late?'<span class="tag bad">Overdue</span>':""}${esc(j.title)}</div>
    <div class="sub">${esc(j.site||"No site")}${j.due?` · due ${shortDay(j.due)}`:""} · ${esc((j.assigneeNames||[]).join(", ")||"Nobody assigned")}${(j.files||[]).length?` · ${j.files.length} document${j.files.length===1?"":"s"}`:""}</div>
    <div class="prog" aria-label="${d} of ${n} done"><span style="width:${pct}%"></span></div></div>
    <div class="amt">${d}/${n}</div></button>`;
}
