const DOORD=["Door: plain / flush","Door: 2 panel","Door: 4 panel","Door: 6 panel (Georgian)","Door: cottage – glazed top, 3 panels below","Door: arched glass top, panels below","Door: half glazed, 2 panels below","Door: 4 small glass squares","Door: centre vertical glass slot","Door: offset vertical glass slot","Door: 3 horizontal glass strips","Door: diamond glass","Door: 2 glass over 2 panels","Door: 4 glass squares over panel","Door: ledged & braced (boarded)","Door: framed, ledged & braced","Door: boarded, small glazed top","Door: 15-lite glazed (French)","Door: 6-lite glazed top, panel below","Door: 2 panel, glazed top (Edwardian)"];
function doorDes(name,X,Y,W,H,C,gl){const k=DOORD.indexOf(name);const st=`stroke="${C.frame}"`;let s=`<rect x="${X}" y="${Y}" width="${W}" height="${H}" fill="${C.panel}" ${st} stroke-width=".8"/>`;
  const P=(fx,fy,fw,fh)=>{const x=X+W*fx,y=Y+H*fy,w=W*fw,h=H*fh,i=Math.min(w,h)*.14;return `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="none" ${st} stroke-width=".6"/>`+(w>8&&h>8?`<rect x="${x+i}" y="${y+i}" width="${w-2*i}" height="${h-2*i}" fill="none" ${st} stroke-width=".35"/>`:"")};
  const G=(fx,fy,fw,fh)=>gl(X+W*fx,Y+H*fy,W*fw,H*fh);
  const grid=(fx,fy,fw,fh,c,r)=>{let q=G(fx,fy,fw,fh);for(let i=1;i<c;i++)q+=`<line x1="${X+W*(fx+fw*i/c)}" y1="${Y+H*fy}" x2="${X+W*(fx+fw*i/c)}" y2="${Y+H*(fy+fh)}" ${st} stroke-width=".7"/>`;for(let j=1;j<r;j++)q+=`<line x1="${X+W*fx}" y1="${Y+H*(fy+fh*j/r)}" x2="${X+W*(fx+fw)}" y2="${Y+H*(fy+fh*j/r)}" ${st} stroke-width=".7"/>`;return q};
  const boards=()=>{let q="";const n=Math.max(4,Math.round(W/9));for(let i=1;i<n;i++)q+=`<line x1="${X+W*i/n}" y1="${Y}" x2="${X+W*i/n}" y2="${Y+H}" ${st} stroke-width=".35"/>`;return q};
  const ledges=framed=>{const lh=H*.05;let q="";[.1,.47,.85].forEach(f=>q+=`<rect x="${X+W*(framed?.1:.04)}" y="${Y+H*f}" width="${W*(framed?.8:.92)}" height="${lh}" fill="${C.panel}" ${st} stroke-width=".5"/>`);
    q+=`<path d="M${X+W*(framed?.12:.08)} ${Y+H*.47}L${X+W*(framed?.86:.9)} ${Y+H*.15}M${X+W*(framed?.12:.08)} ${Y+H*.85}L${X+W*(framed?.86:.9)} ${Y+H*.52}" ${st} stroke-width="${Math.max(1.2,W*.035)}" opacity=".55" fill="none"/>`;return q};
  switch(k){
   case 0:break;
   case 1:s+=P(.15,.08,.7,.38)+P(.15,.54,.7,.38);break;
   case 2:s+=P(.12,.07,.33,.38)+P(.55,.07,.33,.38)+P(.12,.53,.33,.4)+P(.55,.53,.33,.4);break;
   case 3:[.06,.36,.66].forEach((fy,i)=>{const h=i===0?.25:.27;s+=P(.12,fy,.33,h)+P(.55,fy,.33,h)});break;
   case 4:s+=G(.12,.06,.76,.3)+P(.12,.42,.22,.5)+P(.39,.42,.22,.5)+P(.66,.42,.22,.5);break;
   case 5:{const x=X+W*.15,w=W*.7,y=Y+H*.08,h=H*.32,r=w/2;s+=`<path d="M${x} ${y+h}V${y+r*.6}A${r} ${r*.6} 0 0 1 ${x+w} ${y+r*.6}V${y+h}Z" fill="${C.glass}" ${st} stroke-width=".8"/>`+P(.15,.48,.32,.44)+P(.53,.48,.32,.44);break}
   case 6:s+=G(.12,.06,.76,.42)+P(.12,.55,.33,.38)+P(.55,.55,.33,.38);break;
   case 7:s+=G(.2,.12,.22,.14)+G(.58,.12,.22,.14)+G(.2,.32,.22,.14)+G(.58,.32,.22,.14)+P(.15,.55,.7,.37);break;
   case 8:s+=G(.43,.08,.14,.84);break;
   case 9:s+=G(.68,.08,.12,.84);break;
   case 10:[.22,.42,.62].forEach(f=>s+=G(.15,f,.7,.06));break;
   case 11:{const cx=X+W/2,cy=Y+H*.3,rx=W*.22,ry=H*.14;s+=`<path d="M${cx} ${cy-ry}L${cx+rx} ${cy}L${cx} ${cy+ry}L${cx-rx} ${cy}Z" fill="${C.glass}" ${st} stroke-width=".8"/>`+P(.15,.55,.7,.37);break}
   case 12:s+=G(.12,.07,.33,.38)+G(.55,.07,.33,.38)+P(.12,.53,.33,.4)+P(.55,.53,.33,.4);break;
   case 13:s+=grid(.15,.07,.7,.3,2,2)+P(.15,.45,.7,.47);break;
   case 14:s+=boards()+ledges(false);break;
   case 15:s+=`<rect x="${X+W*.08}" y="${Y+H*.04}" width="${W*.84}" height="${H*.92}" fill="none" ${st} stroke-width=".6"/>`+boards()+ledges(true);break;
   case 16:s+=boards()+G(.2,.08,.6,.2)+`<line x1="${X+W*.5}" y1="${Y+H*.08}" x2="${X+W*.5}" y2="${Y+H*.28}" ${st} stroke-width=".7"/>`;break;
   case 17:s+=grid(.1,.05,.8,.82,3,5);break;
   case 18:s+=grid(.1,.06,.8,.42,2,3)+P(.1,.55,.8,.38);break;
   case 19:s+=grid(.12,.06,.76,.36,1,1)+P(.12,.48,.34,.45)+P(.54,.48,.34,.45);break}
  return s}
