  const pn=(a,b,c,d)=>{let r=`<rect x="${a}" y="${b}" width="${c}" height="${d}" fill="${C.panel}" stroke="${C.frame}" stroke-width=".8"/>`;if(c>12&&d>12){if(sty==="raised")r+=`<rect x="${a+c*.18}" y="${b+d*.12}" width="${c*.64}" height="${d*.76}" fill="none" stroke="${C.frame}" stroke-width=".5"/><rect x="${a+c*.24}" y="${b+d*.17}" width="${c*.52}" height="${d*.66}" fill="none" stroke="${C.frame}" stroke-width=".35"/>`;else if(sty==="rib"){const n=Math.max(3,Math.round(c/6));for(let k=1;k<n;k++)r+=`<line x1="${a+c*k/n}" y1="${b+2}" x2="${a+c*k/n}" y2="${b+d-2}" stroke="${C.frame}" stroke-width=".4"/>`}}return r};
