  const close=()=>{window.removeEventListener("resize",size);ov.hidden=true;ov.innerHTML="";document.body.style.overflow=""};
  const base=()=>Math.max(IW,IH);const lw=()=>Math.max(3,Math.round(base()*0.004*wk));
  const snap=()=>{undo.push(JSON.stringify(ops));if(undo.length>60)undo.shift();redo=[]};
  const fit=()=>{const r=stage.getBoundingClientRect();s=Math.min(r.width/IW,r.height/IH);ox=(r.width-IW*s)/2;oy=(r.height-IH*s)/2;draw()};
  const size=()=>{const r=stage.getBoundingClientRect();cv.width=Math.round(r.width*dpr);cv.height=Math.round(r.height*dpr);cv.style.width=r.width+"px";cv.style.height=r.height+"px";draw()};
  const toImg=e=>{const r=cv.getBoundingClientRect();return [(e.clientX-r.left-ox)/s,(e.clientY-r.top-oy)/s]};
  const fsz=o=>Math.round(base()*(o.big?0.045:0.032));
  function textBox(ctx,o){const fs=fsz(o);ctx.font=`700 ${fs}px system-ui, sans-serif`;const tw=ctx.measureText(o.s).width,pd=fs*0.3;return [o.p[0][0]-pd,o.p[0][1]-pd,tw+pd*2,fs+pd*2]}
