    const o=sel!=null?ops[sel]:null;if(o){const [x,y,w,h]=bbox(o);g.save();g.setLineDash([10/s,8/s]);g.lineWidth=2/s;g.strokeStyle="#4f8cff";g.strokeRect(x-6/s,y-6/s,w+12/s,h+12/s);g.setLineDash([]);
      if(o.t!=="pen"&&o.t!=="text")o.p.forEach(q=>{g.beginPath();g.arc(q[0],q[1],13/s,0,7);g.fillStyle="#fff";g.fill();g.lineWidth=3/s;g.strokeStyle="#4f8cff";g.stroke()});g.restore()}
