  function snapEnd(p,skip){if(!snapOn)return p;let best=null,bd=20/s;ops.forEach((o,i)=>{if(i===skip||!two(o))return;const pts=o.p.slice();if(o.t==="rect")pts.push([o.p[0][0],o.p[1][1]],[o.p[1][0],o.p[0][1]]);pts.forEach(q=>{const d=Math.hypot(q[0]-p[0],q[1]-p[1]);if(d<bd){bd=d;best=q}})});return best?[best[0],best[1]]:p}
  function ortho(a,b){if(!snapOn)return b;const dx=b[0]-a[0],dy=b[1]-a[1];const an=Math.abs(Math.atan2(dy,dx)*180/Math.PI)%90;if(an<7||an>83)return Math.abs(dx)>Math.abs(dy)?[b[0],a[1]]:[a[0],b[1]];return b}
  const snapB=(o,p,skip)=>{let b=snapEnd(p,skip);if(b===p&&["line","arrow","dim"].includes(o.t))b=ortho(o.p[0],p);return b};
  const dSeg=(p,a,b)=>{const dx=b[0]-a[0],dy=b[1]-a[1],l=dx*dx+dy*dy||1;let t=((p[0]-a[0])*dx+(p[1]-a[1])*dy)/l;t=Math.max(0,Math.min(1,t));return Math.hypot(p[0]-a[0]-t*dx,p[1]-a[1]-t*dy)};
  function hit(p){const tol=16/s;for(let i=ops.length-1;i>=0;i--){const o=ops[i];const [x,y,w,h]=bbox(o);if(p[0]<x-tol||p[0]>x+w+tol||p[1]<y-tol||p[1]>y+h+tol)continue;
      if(o.t==="text"||o.t==="rect"||o.t==="circle")return i;if(o.p.length===1)return i;for(let k=1;k<o.p.length;k++)if(dSeg(p,o.p[k-1],o.p[k])<o.w/2+tol)return i}return null}
  function askText(cb,cur0){const d=document.createElement("div");d.className="dimask";
    d.innerHTML=`<form class="dimbox"><b>T Write a note</b><input maxlength="80" class="mkti" placeholder="e.g. Move socket here" value="${esc(cur0||"")}"><label class="inl" style="margin-top:6px;color:var(--ink)"><input type="checkbox" class="mktb"> Big writing</label><div class="dimbtns"><button type="button" class="btn mktx">Cancel</button><button type="submit" class="btn primary">Add</button></div></form>`;
    ov.appendChild(d);const inp=d.querySelector(".mkti");setTimeout(()=>inp.focus(),30);d.querySelector(".mktx").onclick=()=>d.remove();d.querySelector("form").onsubmit=e=>{e.preventDefault();const t=inp.value.trim();d.remove();if(t)cb(t,d.querySelector(".mktb").checked)}}
