  ctx.restore();ctx.save();ctx.strokeStyle=o.c||"#444";ctx.lineWidth=lw;ctx.beginPath();p.forEach((q,i)=>i?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1]));ctx.closePath();ctx.stroke();
