        const keep=o=>o.t!=="img";const tp={kind:"nptpl",name,created:Date.now(),withObjs:wo,d:{size:doc.size,orient:doc.orient,scale:doc.scale,paper:doc.paper,w:doc.w,h:doc.h,wallH:doc.wallH||0,layers:doc.layers||null,info:{show:!!(doc.info&&doc.info.show),by:(doc.info||{}).by||""},pages:doc.pages.map(p=>({name:p.name,type:p.type||"",objs:wo?JSON.parse(JSON.stringify(p.objs.filter(keep))):[]}))}};
