  if(pick.emerg)S2("Emergency, fire & first aid plan",[["h","Emergency procedures (CDM 2015 reg. 30-32)"],["rows",[["Site address",cd.address],["what3words",cd.w3w],["Give the site to 999 as",cd.address+(cd.w3w?" (what3words ///"+cd.w3w.replace(/^\/+/,"")+")":"")],["Site manager",cd.manager],["First aider(s)",cd.firstAid],["First aid kit",cd.firstAidKit],["Nearest A&E",cd.hospital],["Fire assembly point",cd.assembly]]],
    ["h2","If there is a fire"],["bul",["Raise the alarm - shout \"FIRE\" and warn everyone, including the household.","Call 999. Only tackle a small fire if it is safe and you are trained.","Leave by the nearest safe route and go to the assembly point: "+(cd.assembly||"________")+".","The site manager checks everyone is out using the sign-in list. Do not go back in."]],
    ["h2","If someone is hurt"],["bul",["Make the area safe. Call the first aider: "+(cd.firstAid||"________")+".","Call 999 for anything serious. Send someone to meet the ambulance.","Record it in the app (Accidents & near misses). Some injuries must be reported to HSE under RIDDOR."]],
    ["h2","Other emergencies"],["bul",["Gas smell or strike: stop work, no flames or switches, open doors, evacuate, call 0800 111 999.","Cable strike: stay clear, keep others away, call the network operator (105) and 999 if anyone is hurt.","Water main strike: isolate if safe, call the water company.","Collapse or structural movement: get everyone out, keep clear, call 999 and the engineer"+(cd.engineer?" ("+cd.engineer+")":"")+"."]],
    ["h2","Fire precautions on site"],["bul",["Fire point with extinguishers (CO2 for electrical, foam / water for general) kept by "+(cd.assembly?"the site entrance":"the site entrance"),"Hot works permit for cutting, grinding and torch-on; fire watch for an hour after","Waste removed regularly; no burning on site; flammables and gas bottles stored outside and secure","Escape routes and the household's exits kept clear at all times"]]]);
  if(pick.drr)S2("Design risk register",[["h","Design risk register (CDM 2015 reg. 9)"],["rows",head],["p","Hazards the design creates or leaves for the people building, maintaining or using the building. Designers eliminate what they can, reduce the rest and record what is left for the contractor."],
    ["tablew",[44,62,46,178-152],[["Hazard","How the design deals with it","Risk left for the contractor","Who"],risks2.map(([k,l])=>[l.split(" (")[0],"",CDM_CTRL[k]||"See RAMS",""]).concat(cd.designRisks?[[cd.designRisks,"","",""]]:[]).concat([["","","",""],["","","",""]])]],["sign",[["Designer",cd.designer],["Principal designer",many?(cd.pdName||co.name):"-"],["Principal contractor",co.name]]]]);
